// Generated by `pnpm bundle:agent-prompts` from ./agents/*.md. Do not edit.

/** This program's agent prompts by task type, verbatim. */
export const AGENT_PROMPTS: Readonly<Record<string, string>> = {
  'ai-observability':
    "---\ntype: ai-observability\nflow: integration-v2\nlabel: Add AI Observability\nmodel_pi: openai/gpt-5.6-terra\neffort_pi: high\nmodel_sdk: claude-sonnet-5\neffort_sdk: high\nskills: []\nallowedTools: [Read, Write, Edit, Glob, Grep, load_skill_menu, install_skill]\ndisallowedTools: [enqueue_task]\ndependsOn: [capture]\noptional: true\n---\n\n## Goal\n\nAdd AI Observability to the LLM calls this project already makes. Read the\nupstream handoffs and inspect the call sites, not just the dependency names.\nIf there are no LLM calls, complete as `not needed` with the reason and make no\nchanges. Do not install a vendor SDK, add a demo call, or use manual capture to\ninvent an AI feature in an app that has none.\n\nFor existing LLM calls, load the `ai-observability` skill menu and install the\nvariant matching the calling code's language and provider or agent framework.\nFollow that skill's selection rules and instrumentation references. Manual\ncapture is appropriate only for existing calls without a supported wrapper.\nInstrument against the provider SDK version the app already uses; never\nrequire, assume, or request an upgrade of the app's own dependencies — if the\nwrapper cannot support the app's version, fall back to manual capture or\nreport why. Reuse the PostHog client and identity established earlier in this\nrun. Follow the skill's privacy-mode instructions: default new SDK clients to\n`privacy_mode=False` (Python) or `privacyMode: false` (Node), so prompt and\ncompletion content is captured. Preserve existing privacy settings, redaction,\nand explicit user or project requirements. Use the variant's documented controls\nwhere capture is configured elsewhere; do not strip manual-capture content by\ndefault. If a variant cannot be chosen from the code, report the ambiguity as\n`not needed`; this default run does not ask the user to choose a provider.\n\nThis is the instrumentation part of a larger integration. Name the packages\nthis task needs in your handoff for review to install; do not edit dependency\nmanifests, and never write a version number you invented — the package manager\nresolves real versions when review installs by name. Defer the skill's\npackage-manager and import-check commands to that task. For Go, review adds the\nmodules with `go get` and `go mod tidy`; do not hand-edit `go.mod` or `go.sum`.\nDo not run the app or make paid LLM calls. Use `check_env_keys` and\n`set_env_values` for environment files, using the project credentials supplied\nby the wizard.\n\n## How you know you succeeded\n\nExisting LLM calls are wired using the selected skill, or the handoff clearly\nexplains why this task was not needed. List the variant, changed files, declared\ndependencies, and a concrete call path the user can trigger to verify the\nsession/trace/generation tree. Include the skill's **Privacy mode** handoff:\nthe effective setting, the file and line to edit, when to enable it, and the\n[privacy-mode docs](https://posthog.com/docs/ai-observability/privacy-mode). Pass any\ndeferred dependency work to review.\nDescribe delivery as unverified unless this run actually observed it; do not\npublish a separate setup report.\n",
  capture:
    "---\ntype: capture\nflow: integration-v2\nlabel: Capture events\nmodel_pi: openai/gpt-5.6-terra\neffort_pi: medium\nmodel_sdk: claude-sonnet-5\neffort_sdk: high\nskills: [integration-v2-capture, posthog-best-practices]\nallowedTools: [Read, Write, Edit, Glob, Grep]\ndisallowedTools: [enqueue_task]\ndependsOn: [install, init, identify]\n---\n\n## Goal\n\nDecide which events are worth capturing in this app, then instrument them in the\nsame pass — read each file once, choose the events, and add the capture calls\nwhile the file is already open. Instrumenting the events is the job; everything\nbelow is a rule you apply while you do it, not work of its own.\n\nThe identify step's handoff already says how this app attributes events. Read it\nonce, up front, and follow it:\n\n1. Where identity is established for you — a client library that remembers it, or a\n   framework middleware that binds it per request — a plain capture is already\n   attributed. Write the plain call and move on. Do not add a context of your own,\n   and do not go looking through the call tree to prove it.\n2. Where the handoff says it is not — no middleware, or a call path that runs\n   outside the request — tag that call with the distinct id and the session id.\n\nWhere the project has no identity to begin with — the identify step found nothing to\nwire, because the app has no accounts or login — personless events are the right\nanswer. Capture plainly, with no id and no placeholder, and say so in your handoff.\n\nThe placeholder is for the third case only: identity exists in this project, but no\nstable id reaches the call site. Do not guess at the id and do not invent a fallback —\npass `DISTINCT_ID` there so the gap is visible in the code, and say in your handoff\nthat identity exists but could not be reached, so the report calls it out as an issue\nto follow up rather than claiming events that belong to nobody.\n\nNever put PII in an event. When new information about the user surfaces, tag the\nuser the way the identify docs describe, not the event.\n\n## How you know you succeeded\n\nThe meaningful user actions across the app have capture calls that fire on the\nreal action, not on page load, each one attributable to the user who took it, and\n`.posthog-wizard-cache/.posthog-events.json` lists the events you instrumented.\n\nYou do not run builds, linters, or tests — the review task verifies the whole integration after you; your edits just need to be right by reading.\n",
  dashboard:
    '---\ntype: dashboard\nflow: integration-v2\nlabel: Create a starter dashboard\nmodel_pi: openai/gpt-5.6-terra\neffort_pi: low\nmodel_sdk: claude-sonnet-5\neffort_sdk: high\nskills: [integration-v2-dashboard, integration-v2-insight, integration-v2-mcp]\nallowedTools: [Read, Glob, Grep, posthog_exec]\ndisallowedTools: [Write, Edit, Bash, enqueue_task]\ndependsOn: [capture]\n---\n\n## Goal\n\nCreate a starter PostHog dashboard with a few insights built on the events this\nintegration instruments, using the PostHog MCP.\n\n## How you know you succeeded\n\nA dashboard exists with a handful of insights on the captured events, and you hand\noff its URL for the report to link.\n',
  'error-tracking':
    "---\ntype: error-tracking\nflow: integration-v2\nlabel: Add error tracking\nmodel_pi: openai/gpt-5.6-terra\neffort_pi: low\nmodel_sdk: claude-sonnet-5\neffort_sdk: high\nskills: [integration-v2-error-tracking-step, posthog-best-practices]\nallowedTools: [Read, Write, Edit, Glob, Grep]\ndisallowedTools: [enqueue_task]\ndependsOn: [install, init]\n---\n\n## Goal\n\nMake the errors the app does not catch reach PostHog, by whatever means the SDK\noffers for that. Which means depends on the SDK: some autocapture exceptions once\nyou enable it at init, some wire into the framework's own error handler, some give\nyou a boundary to mount at the app entry. Follow the docs and the reference example\nfor this one, and set it up in one place — never manual capture calls sprinkled\nacross files.\n\nThe SDK is already installed and initialized (see the context from previous steps);\nbuild on that, do not re-check it.\n\nThis is an instrument-only task. Do not install dependencies, run the build, run\ntests, or start the app — a later `build` step does all verification. Stay inside\nthis project's directory and set up that one place; that is the whole job.\n\n## How you know you succeeded\n\nAn error the app does not catch reaches PostHog, through the mechanism this SDK\ngives you rather than one you invented. You did not install anything, run a build,\nlint, or tests (the review task verifies after you), search outside the project, or read through the whole app or hand-wrap\nindividual components or routes.\n",
  identify:
    "---\ntype: identify\nflow: integration-v2\nlabel: Wire user identification\nmodel_pi: openai/gpt-5.6-terra\neffort_pi: medium\nmodel_sdk: claude-sonnet-5\neffort_sdk: high\nskills: [integration-v2-identify, posthog-best-practices]\nallowedTools: [Read, Edit, Glob, Grep]\ndisallowedTools: [enqueue_task]\ndependsOn: [install, init]\n---\n\n## Goal\n\nWire user identification so everything the app reports — its errors as much as its\nevents — carries who the user is.\n\nThe distinct id is the app's own stable identifier for the user — a primary key, a\nuuid, a resource name. Not an email and not a username: those are PII and they change;\nsend them as person properties instead. Fall back to email only when the app truly has\nno other stable key, and say so in your handoff — do not invent one by altering the\napp's schema.\n\nWork out first what you are in: a client-only app, a fullstack or SSR app, or a\nbackend or API. Identification takes a different shape in each, and the shape\nfollows from that answer:\n\n1. Client and frontend — identify once, and only once, when the user logs in or\n   registers, and reset when they log out. That single call merges what was already\n   captured against the anonymous id into the stable distinct id you give it. The\n   library persists identity from there, so everything after it is attributed to the\n   same user until reset — nothing needs re-identifying per page or per event.\n2. Fullstack or SSR — your identification hinges on the client side, where the\n   identity is persisted. The distinct id and the session id travel on every request\n   the frontend sends, in the header format the docs describe. Some libraries already\n   do this for you; read the docs and the example app before wiring it by hand. The\n   backend should take note of the session and distinct id as soon as possible and\n   either carry it to every capture or use the identified context to identify the\n   request.\n3. Backend and API — a server serves many users at once, so identity belongs to the\n   request, never to the process. Take it from the incoming request or the ambient\n   context, as far as the app allows. Then either tag each event with the distinct\n   id and session id, or, where the SDK has contexts, open one around the whole\n   request and identify that context so everything the request reports inherits it.\n   Where the SDK ships a middleware for this framework, that is what does this — use\n   it rather than writing your own. Read the docs and the example app.\n\n## How you know you succeeded\n\nIdentification matches the kind of app you are in. While a user is known, what the\napp reports is attributable to them with a stable distinct id — the errors it\nreports, not only the events — established at the boundary the SDK gives you rather\nthan repeated at call sites that already inherit it. Where the app changes who the\nuser is mid-request, that boundary cannot know it yet, and establishing identity\nagain there is the point, not a duplicate. Your handoff names the files you\nchanged, how identity is established in them, and what a later step must do for its\nown calls to inherit it — whether that is nothing at all, or tagging each call\nitself. If the app has no auth or user concept, say so and stop.\n\nYou do not run builds, linters, or tests — the review task verifies the whole integration after you; your edits just need to be right by reading.\n",
  init: "---\ntype: init\nflow: integration-v2\nlabel: Set up PostHog initialization\nmodel_pi: openai/gpt-5.6-terra\neffort_pi: low\nmodel_sdk: claude-sonnet-5\neffort_sdk: medium\nskills: [integration-v2-init, posthog-best-practices]\nallowedTools: [Read, Write, Edit, Glob, Grep]\ndisallowedTools: [enqueue_task]\ndependsOn: []\n---\n\n## Goal\n\nInitialize PostHog: create the framework's init point so the SDK is configured\nonce and available across the app, set the PostHog environment variables through\nthe wizard tools, and document those keys in `.env.example` for other developers.\n\nTry to follow these principles, in order: codebase convention, don't make any\nunnecessary changes, keep the change as lean as possible for an easy review, and\nfollow the shape of the examples provided. How call sites reach the client is\npart of the shape: reach it the way the docs and the example project reach it.\n\n## How you know you succeeded\n\nThe init file exists and the PostHog env keys are present. Keys live in the env\nfile, never hardcoded in source, and `.env.example` lists the key names (with\nplaceholder values) so the next developer knows what to set. Your handoff names the\nfiles you changed, how the client is constructed in them, and how a call site\nreaches that client — every step after you has to reach the same one the same way.\nIf the app ships a Content-Security-Policy, the handoff also names exactly\nwhich directives you touched (`script-src`, `connect-src`, `worker-src`) and\nwhich you left alone — the review verifies directive-by-directive, and an\nunnamed directive reads as unhandled, not as fine.\n\nYou do not run builds, linters, or tests — the review task verifies the whole integration after you; your edits just need to be right by reading.\n",
  install:
    "---\ntype: install\nflow: integration-v2\nlabel: Add the PostHog SDK to the manifest\nmodel_pi: openai/gpt-5.6-terra\neffort_pi: low\nmodel_sdk: claude-haiku-4-5\nskills: [integration-v2-install]\nallowedTools: [Read, Edit, Glob, Grep, Bash]\ndisallowedTools: [enqueue_task]\ndependsOn: []\n---\n\n## Goal\n\nInstall the PostHog SDK with the project's own package manager, so the real\npublished version lands in the manifest and the lockfile — not one you made up.\nRun the manager's add command with the bare package name and let it resolve the\nversion: `npm install <pkg>` (or the project's pnpm/yarn/bun), `pip install <pkg>`,\n`composer require <pkg>`, `bundle add <pkg>`, `gem install <pkg>`. Never invent a\nversion — one that was never published fails the whole run with `ETARGET`, and\nguessing another just fails again. The only version you write by hand is one copied\nfrom the framework reference example, and only in the environment fallback below.\n\nAdd the client library, plus the server library if the app has server-side code\nthat sends events. If the SDK is already installed, leave it and say so.\n\nSome ecosystems pin an explicit version in a manifest no install command resolves\n(Swift SPM, Gradle). There, declare the dependency the way the framework reference\nshows and take the version from the SDK's latest release — do not invent one.\n\nAttempt the install once. If it fails on something you own — a wrong package name or\nthe wrong manager — fix that and run it one more time.\n\nBut if the environment prevents the install through no fault of your change, do NOT\nspiral retrying it. These are environment failures, not yours:\n\n- a peer-dependency conflict the project already had (npm `ERESOLVE`),\n- a dependency already in the manifest that itself does not resolve (a bad or yanked\n  version, a package that no longer exists) — the failure names a package that is not\n  PostHog,\n- the package manager crashing on the project's existing dependency graph or a\n  corrupt/incompatible lockfile (e.g. npm `Cannot read properties of null`),\n- the package manager itself failing to run or provision — corepack unable to\n  switch to a pinned version (`Failed to switch pnpm to …`, `Cannot find matching\n  keyid`), a missing manager binary, a toolchain the machine does not have,\n- no network or registry reachable.\n\nThe test: if the failure names your PostHog package or your command, it is yours to\nfix; if it names another dependency, a version pin the project set, or the toolchain\nitself, it is the environment — fall back and move on.\n\nWhen you hit one of those, fall back: add the PostHog package to the manifest by hand\nat a known-good version, so the dependency is still declared for the later steps and\nfor the user's own install. Use the framework reference example's spec if it names\none; otherwise use a caret on the SDK's current known-good release — `posthog-js`\n`^1.407.2`, `posthog-node` `^5.46.1`, `posthog-php` `^4.12.1`, `posthog` (Python)\n`^7.29.0`, `posthog-ruby` `^3.21.0`. The caret keeps it current without pinning a\npatch; never invent a version that was never published. Then move on, and say in your\nhandoff exactly what failed and the command\nyou ran, so the review step and the report surface it.\n\n## How you know you succeeded\n\nThe SDK resolved and installed at its real version, or you have reported plainly in\nyour handoff why the environment stopped it. Your handoff names the manifest and the\npackage, so later steps import it under the name they will actually get.\n",
  'integrate-posthog':
    "---\ntype: integrate-posthog\nflow: integration-v2\nseed: true\nmodel_pi: openai/gpt-5.6-terra\neffort_pi: medium\nmodel_sdk: claude-sonnet-5\neffort_sdk: high\nskills: []\nallowedTools: [Read, Glob, Grep]\ndisallowedTools: [Write, Edit, Bash, complete_task]\ndependsOn: []\n---\n\n## Goal\n\nPlan a PostHog integration and seed the task queue with this graph:\n\n- `install` and `init`, independent of each other.\n- `identify` and `error-tracking`, each after `install` and `init` and independent\n  of one another, so they run in parallel. `error-tracking` makes the errors the app\n  does not catch reach PostHog, by whatever means the SDK offers for that — it needs\n  the SDK installed and initialized, not the events.\n- `capture`, after `identify` — it decides the events and instruments them, and it\n  reads how identity is already established before it instruments anything.\n- `ai-observability`, after `capture`, parallel to `error-tracking` — it instruments\n  existing LLM calls, or reports that none apply. Queue it on every default run; the\n  task checks applicability rather than the planner guessing from a package name.\n- `logs`, after `ai-observability` — it configures log capture on supported\n  platforms, or reports why it does not apply. Queue it even when AIO will be\n  skipped. These tasks run sequentially because both instrument the same entry\n  and initialization files, and Logs preserves any tracing provider AIO\n  configures — an ordering-dependent instruction. (Their dependency installs\n  are deferred to review, so manifests are not the conflict.)\n- `review`, after `install`, `init`, `identify`, `capture`, `error-tracking`,\n  `ai-observability`, and `logs` —\n  it installs the dependencies, verifies the project builds/typechecks/lints, and\n  reviews every change the run made, fixing what fails. There is no separate build\n  step: verifying and reviewing are one pass over the same changeset.\n- `dashboard`, after `capture`, independent of AIO, Logs, and `review` — it builds insights from the\n  instrumented events, which `capture` has already defined; it needs no code review.\n- `report`, after `dashboard` **and** `review` — it writes the setup report last, so\n  it describes the integration as reviewed rather than as first written.\n\nIf `enqueue_task` does not offer a task's type, this run excludes that product\n— skip it rather than retrying, and hang nothing off it.\n\n## How you know you succeeded\n\nEvery task in the graph is queued with that dependency shape, the report last,\nand the first task runnable. Keep labels short — the action in a few words.\n",
  logs: "---\ntype: logs\nflow: integration-v2\nlabel: Add log capture\nmodel_pi: openai/gpt-5.6-terra\neffort_pi: medium\nmodel_sdk: claude-sonnet-5\neffort_sdk: high\nskills: []\nallowedTools: [Read, Write, Edit, Glob, Grep, load_skill_menu, install_skill]\ndisallowedTools: [enqueue_task]\ndependsOn: [ai-observability]\noptional: true\n---\n\n## Goal\n\nConfigure PostHog log capture for this project's supported runtimes. Load the\n`logs` skill menu, install its matching skill, and read the platform reference\nbefore editing. Inspect the runtime and existing logging setup; use the\ndocumented OTLP exporter or SDK-native log capture for that platform. If the\napp already uses OpenTelemetry, write against its existing OTel version and\nname exporter packages compatible with it — never require, or write code that\nassumes, an upgrade of a package this integration did not introduce. A\nbrowser-only app must not receive a server exporter. If no documented setup\napplies, complete as `not needed` and explain why.\n\nExport only log lines this integration adds. Create a dedicated logger for the\nPostHog exporter and emit a few purpose-written lines at meaningful points the\napp already passes through. Even where the platform reference attaches the\nexporter to the application's root or existing loggers, do not — the app's\nexisting logs are data this run has no mandate to export, and every line that\nleaves must be visible in this run's diff. Reuse any existing PostHog log\nexport and leave all existing handlers and outputs intact; if capture is\nalready configured, report that without adding a second exporter. Preserve any\ntracing provider AIO configured in the previous step. Do not export secrets,\nrequest bodies, or user data, and do not scatter logs through unrelated code.\n\nThis is the instrumentation part of a larger integration. Instead of the\nstandalone skill's install command, name the required packages in your handoff\nand leave installation, manifest and lockfile updates, builds, and lint to\nreview. Do not edit dependency manifests or write a version number you\ninvented — the package manager resolves real versions when review installs by\nname. Use `detect_package_manager` if needed. Use\nthe wizard's supplied project and region and the env names from upstream\nhandoffs; inspect and write environment files only through `check_env_keys`\nand `set_env_values`. Do not request credentials or select a different project.\nIf required configuration is unavailable, report what is missing instead of\nguessing a region.\n\n## How you know you succeeded\n\nLog capture is configured once for the supported runtime, was already present,\nor has a clear skip reason. The handoff names the changed files, packages, env\nvariable names (never values), and any dependency work for review. Give a\nspecific code path the user can trigger to produce one of the added log lines\nand find it in PostHog Logs; delivery remains unverified until observed. Note\nfor the report that only lines added by this run are exported, and the one-line\nchange that routes the app's existing loggers into the same exporter if the\nuser wants more. Do not publish a separate report.\n",
  report:
    "---\ntype: report\nflow: integration-v2\nlabel: Write the setup report\nsink: true\nmodel_pi: openai/gpt-5.6-terra\neffort_pi: low\nmodel_sdk: claude-sonnet-5\neffort_sdk: high\nskills: [integration-v2-report, integration-v2-notebook, integration-v2-mcp]\nallowedTools: [Read, Glob, Grep, posthog_exec]\ndisallowedTools: [enqueue_task]\ndependsOn: [dashboard, review]\n---\n\n## Goal\n\nCompose the setup report summarizing what this integration did, drawing only on\nwhat the run itself recorded: the queue log and event plan in\n`.posthog-wizard-cache/` (`queue.json` and `.posthog-events.json`), and the\nhandoff each step left behind. Then publish it with a single `publish_handoff`\ncall. The same call mirrors the markdown into a shareable PostHog notebook. The notebook skill says what the result\nmeans and covers older wizards. Do not write a report file. The handoff call\nand the notebook are how the report reaches the user.\n\nSeparate what the run verified from what it did not. A passing build proves the\ncode compiles, not that events flow — never write that an event was captured\nunless the run observed it arrive. Where a step failed or was skipped, say so\nplainly instead of rounding it up to success. Anything only the user can confirm\nbelongs in a checklist to work through before merging, each item naming the file\nand line to look at.\n\nWhere a handoff carries a report section, that step already wrote the part of\nthe report it owns. Include it as its own section instead of rewriting or\nsummarizing it, and do not restate its contents elsewhere.\n\nWhere a handoff reports something a step could not resolve — attribution it could not\nestablish, a question the step before it left open — that is not a caveat to bury in\nprose. Raise it as its own issue to follow up, saying what is unresolved and what it\ncosts if left alone. A `DISTINCT_ID` placeholder left at a call site means no stable id\nwas available: name every file and line carrying one, so the user knows what to replace\nbefore those events mean anything.\n\n## How you know you succeeded\n\nOne `publish_handoff` call went through with the full report: what was\ninstalled and initialized, the events captured, whether identify was wired or\nskipped, error tracking added, AI Observability and Logs configured, skipped, or\nfailed with reasons, the dashboard link, any build conflict in full,\nand the next steps for the user. Every claim in it traces to a handoff, and\nwhat the run could not confirm reads as unconfirmed. The notebook mirror is\nbest effort: when it was created, the user has its link, and when it wasn't,\nyour final message says why, and when an update failed, that the notebook holds the earlier version. A missing notebook never fails this task.\n",
  review:
    "---\ntype: review\nflow: integration-v2\nlabel: Verify and review the integration\nmodel_pi: openai/gpt-5.6-sol\neffort_pi: medium\nmodel_sdk: claude-sonnet-5\neffort_sdk: high\nskills: [posthog-best-practices, integration-v2-build]\nallowedTools: [Read, Edit, Glob, Grep, Bash]\ndisallowedTools: [enqueue_task]\ndependsOn: [install, init, identify, error-tracking, capture, ai-observability, logs]\n---\n\n## Goal\n\nYou are the last hands on the code. First make the integration run, then review it,\nthen leave it building to the best of your ability. Do both in one pass, verifying and reviewing are the same\nreading of the same changeset.\n\n**Install and verify.** The earlier steps edited code but did not install —\ninstall now, then verify the project builds, typechecks, and lints, whichever\nof those it defines. Install what the manifest declares plus every package the\nupstream handoffs name, adding the named ones by bare name with the project's\npackage manager so it resolves real versions. The app's existing dependencies\nare not yours to touch: never upgrade, downgrade, or re-add a package this\nintegration did not introduce. If an instrumentation package's peer range\nconflicts with a dependency the app already has, install an older\ninstrumentation version that fits the app's existing versions — find it with\nthe package manager, stepping down major versions (`pkg@^7`, then `@^6`,\n…) for a few attempts rather than looking for documentation of one. If none\nfits, revert that piece of instrumentation, leave the app's dependency alone,\nand record the incompatibility so the report can say what was skipped and why. An optional upstream task\n(AI Observability, Logs) may have failed and left partial edits no handoff\ndescribes — install and build either way, and let the build surface stray\nimports; fix or revert them like any other defect. Do not run the test suite; the\nruntime does not allow it, and a green build is the bar. A bad version only surfaces\nhere: if the install fails because a declared version does not exist (npm `ETARGET`,\n\"no matching version\", a yanked release), do not guess pins — reinstall the\npackage by bare name and let the package manager pick, matching the framework\nreference example's spec only if that also fails. If the failure is the environment, not the\nintegration's own change (a pre-existing broken dependency, a package manager that\ncannot provision), note it and move on; do not spiral.\n\n**Review, as a strict reviewer who did none of the writing.** The changeset is\nalready handed to you: `read_handoffs` returns every upstream task's handoff, and\neach one names the files it touched and what it changed in them. That union of\ntouched files IS the changeset. Read each changeset file once and judge it — after\nyour own edit you already know its contents, so do not re-read it. Read beyond the\nchangeset only where a dimension sends you: one neighboring example per pattern you\nare checking, and the callers of code that changed. Nothing else — not the SDK's\ninstalled internals, not other tasks' instructions, not a diff of the whole tree;\nthe handoffs are the signal.\nThe handoffs also carry what no file shows — env values written through\n`set_env_values`, manifest edits. Judge each change against these dimensions, in\norder:\n\n1. Minimal — every line earns its place. Delete helpers nothing calls, defensive\n   wrapping around code that cannot fail, config for features that were not set up,\n   and comments that narrate what a line does or that it was added.\n2. Unrelated — the run must not have changed behavior outside the integration.\n   Revert reformatting, renames, or edits in code the integration never needed.\n3. Codebase patterns — for each kind of edit (client construction, how call sites\n   reach it, config and env access, imports, naming, comment density), find one\n   neighboring example in this project and compare. If a change invented a seam the\n   project does not have — a registry, locator, wrapper, or app the codebase never\n   uses — replace it with the closest pattern the project actually uses.\n4. Example shapes — where the framework reference example shows a shape for init or\n   instrumentation, the code should be recognizably that shape adapted to this\n   codebase. Codebase idiom beats the example when they conflict; the PostHog\n   correctness rules you were given beat both.\n\nYou never change what is captured — event names, properties, and where events fire\nare a contract the dashboard and report are built on. Refactor how, and kill bad\nchanges; never alter the what.\n\nEvents reaching PostHog in production is the point of this code, so a capture wired\nto a place it will never fire, an uninitialized SDK, or a call the runtime silently\ndrops is squarely yours to catch and fix — it is a code defect. What you cannot do is\nconfirm delivery: you cannot exercise the app, and you never treat \"I could not\nverify events arrive\" as a finding.\n\nStay inside verify-and-review. These are not your job:\n\n- The report or the dashboard — other tasks own those; do not write or judge them.\n- Product or analytics design — which events are worth tracking, identity strategy,\n  framework-version tradeoffs. The changeset is the decision; review whether the code\n  implements it correctly, not whether it was the right decision.\n- Anything the integration did not touch. Do not widen scope to pre-existing issues.\n\nIf you notice something real but out of scope, leave it — a one-line mention in your\nhandoff, no more. Only flag what you can pin to a specific line and dimension — no\ntaste-based rewrites, and never expand the integration. For each fix, ask what would\nbehave differently if it were wrong, and check by reading the callers. After any\nchange, re-run the build or lint and confirm it still passes.\n\n## How you know you succeeded\n\nThe project installed and builds, typechecks, and lints as well as it did before the\nrun; you can name each review dimension and say it passes; and your fixes are in the\nfiles. If the build or lint fails only on pre-existing errors you did not introduce,\nthat still counts — put a one-line summary in the `conflict` field and the detail in\nwhat you did. Reserve a failed status for when your own changes break the build. Put\nthe number of fixes and the dimension each addressed in your handoff.\n",
  warehouse:
    "---\ntype: warehouse\nflow: integration-v2\nlabel: Connect your data sources\nrunnerSeeded: true\nmodel_pi: openai/gpt-5.6-terra\neffort_pi: medium\nmodel_sdk: claude-sonnet-5\neffort_sdk: medium\nskills: [integration-v2-warehouse, integration-v2-mcp]\nallowedTools: [Read, Glob, Grep, wizard_ask, posthog_exec]\ndisallowedTools: [Write, Edit, Bash, enqueue_task]\ndependsOn: []\n---\n\n## Goal\n\nConnect the data sources listed in your task input to PostHog's data warehouse,\nso the project's own data can be queried next to the events this run\ninstruments. The wizard found them in the project; your job is to turn each one\ninto a real connection, or into a link the user can finish in the browser.\n\nYou are the only step that stops to ask the user for anything, so make the ask\ncount: gather what a source needs in one `wizard_ask` call, tagged with that\nsource's kind as its `subject`. A decline answers that one source. Move on to\nthe next source rather than re-asking or ending the round.\n\nTouch no project code. This step connects data; it does not edit the app.\n\n## How you know you succeeded\n\nEvery source in your input reached a decided end: connected in PostHog, handed\nback as a link to finish, or skipped with a reason. Your handoff carries a\nfinished report section naming each source and which of those three it was, so\nthe reporting step can include it as it stands.\n\nA link is a handoff, not a connection. Your report section opens with the count\nyou connected, and your `complete_task` status matches it: `done` only when you\nconnected at least one source.\n",
};
